static __init int init_tdx_module_extensions(void)
{
	struct tdx_sys_info_ext sysinfo_ext;
	int ret;

	if (!(tdx_sysinfo.features.tdx_features0 & TDX_FEATURES0_EXT))
		return 0;

	ret = get_tdx_sys_info_ext(&sysinfo_ext);
	if (ret)
		return ret;

